<?php require_once __DIR__.'/../_bootstrap.php'; $a=user();$s=db()->prepare('SELECT id,full_name,shop_name,phone,email,profile_image,role,status,trial_ends_at,subscription_start_at,subscription_end_at,subscription_status,created_at FROM users WHERE id=?');$s->execute([$a['id']]);$u=$s->fetch();if(!$u)fail('User not found',404);$end=$u['subscription_end_at']?:$u['trial_ends_at'];$u['days_remaining']=$u['role']==='admin'?null:max(0,(int)ceil((strtotime($end)-time())/86400));$u['payment_whatsapp']=PAYMENT_WHATSAPP;out(['success'=>true,'user'=>$u]);
